package net.minecraft.server.level;import java.util.*;import net.minecraft.world.level.*;import net.minecraft.world.phys.*;import net.minecraft.core.BlockPos;import net.minecraft.world.level.block.state.BlockState;public class ServerLevel extends Level{public boolean grief=true;public Set<BlockPos> unloaded=new HashSet<>();public Map<BlockPos,BlockState> blocks=new HashMap<>();public boolean hasChunkAt(BlockPos p){return !unloaded.contains(p);}public BlockState getBlockState(BlockPos p){return blocks.getOrDefault(p,new BlockState(true));}public BlockHitResult clip(ClipContext c){for(int i=0;i<=1000;i++){double t=i/1000.;BlockPos p=new BlockPos((int)Math.floor(c.from().x()+(c.to().x()-c.from().x())*t),(int)Math.floor(c.from().y()+(c.to().y()-c.from().y())*t),(int)Math.floor(c.from().z()+(c.to().z()-c.from().z())*t));if(!getBlockState(p).air)return new BlockHitResult(p);}return new BlockHitResult(null);}}
